// Keep public landing-page actions usable during dev-client hydration/reloads.
function Link({ href, onClick, ...props }: AnchorHTMLAttributes<HTMLAnchorElement> & { href: string }) {
  return <a href={href} onClick={(event) => {
    onClick?.(event);
    if (!event.defaultPrevented && event.button === 0 && !event.metaKey && !event.ctrlKey && !event.shiftKey && !event.altKey) {
      event.preventDefault();
      window.location.assign(href);
    }
  }} {...props} />;
}

export function ProductPlans() {
  const t = useProductText(), { locale } = useI18n();
  const identity = useAuthStore(s => s.status + ':' + s.sessionRevision);
  const plans = useQuery({ queryKey: ['candidate-plans', identity], queryFn: () => billingApi.plans('CANDIDATE') });
  const features = [['career.builder', 'builder'], ['career.match', 'recommended'], ['career.alerts', 'alerts'], ['career.auto_apply', 'auto'], ['career.coach', 'coach']] as const;
  return <section id="pricing" className="mx-auto max-w-7xl px-5 py-20 sm:px-8"><div className="mb-10 max-w-2xl"><p className="mb-3 text-xs font-semibold uppercase tracking-widest text-indigo-600 dark:text-indigo-300">EasyJob · {t('subscription')}</p><h2 className="text-3xl font-semibold tracking-tight sm:text-4xl">{t('plans')}</h2><p className="mt-4 text-muted-foreground">{t('plansBody')}</p></div>{plans.isPending ? <SkeletonRows rows={3} cols={3} /> : plans.isError ? <Failure retry={() => plans.refetch()} /> : <div className="grid gap-5 md:grid-cols-3">{plans.data.map(plan => { const premium = !!plan.features['career.auto_apply']; const popular = plan.name === 'PRO'; return <article key={plan.id} className={`relative flex flex-col rounded-3xl border p-7 ${premium ? 'border-indigo-300 bg-indigo-50/60 dark:border-indigo-700 dark:bg-indigo-950/30' : 'border-border bg-card'}`}>{(popular || premium) && <span className="absolute -top-3 start-6 rounded-full bg-indigo-600 px-3 py-1 text-xs font-semibold text-white">{popular ? t('mostPopular') : t('maximumAi')}</span>}<h3 className="text-lg font-semibold">{premium ? 'Premium' : plan.name}</h3><p className="my-6 text-3xl font-semibold tracking-tight">{formatMoney(plan.priceCents, plan.currency, locale)}<span className="ms-1 text-sm font-normal text-muted-foreground">/ {t(plan.billingInterval)}</span></p><ul className="mb-8 space-y-3 text-sm">{['find', 'saved', 'cvs', 'ats', ...features.filter(([feature]) => plan.features[feature] === true).map(([, label]) => label)].map(label => <li key={label} className="flex gap-2"><Check className="size-4 shrink-0 text-indigo-600 dark:text-indigo-300" />{t(label)}</li>)}</ul><Button variant={premium ? 'default' : 'outline'} asChild className="mt-auto w-full"><Link href="/candidate/subscription">{t('choosePlan')}<ArrowUpRight className="ms-2 size-4" /></Link></Button></article>; })}</div>}</section>;
}

