    <section id="how-it-works" className="mx-auto max-w-7xl px-5 py-20 sm:px-8"><div className="mb-10 max-w-2xl"><p className="mb-3 text-xs font-semibold uppercase tracking-widest text-indigo-600 dark:text-indigo-300">{t('how')}</p><h2 className="text-3xl font-semibold tracking-tight sm:text-4xl">{t('workflow')}</h2><p className="mt-4 text-muted-foreground">{t('workflowBody')}</p></div><div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-5">{steps.map((Icon, i) => <article key={i} className="border-t-2 border-indigo-100 pt-6 dark:border-indigo-900"><Icon className="mb-4 size-6 text-indigo-500" /><h3 className="font-semibold">{t(`step${i + 1}`)}</h3><p className="mt-3 text-sm leading-6 text-muted-foreground">{t(`step${i + 1}Body`)}</p></article>)}</div></section>
